  overflow: hidden;
  cursor: pointer;
}

div.jx-handle {
  position: absolute;
  height: 100%;
  width: 50px;
  cursor: col-resize;
  z-index: 15;
  margin-left: -25px;
}

.vertical div.jx-handle {
  height: 50px;
  width: 100%;
  cursor: row-resize;
  margin-top: -26px;
  margin-left: 0;
