}

.vertical div.jx-control {
  height: 1px;
  width: 100%;
  background-color: var(--border-orange);
  position: relative;
  top: 50%;
  transform: translateY(-50%);
}

div.jx-controller {
  position: absolute;
  margin: auto;
  top: 0;
  bottom: 0;
  height: 50px;
  width: 50px;
  margin-left: -3px;
  background-color: var(--white);
  border-radius: 150%;
  border: 1px solid var(--border-orange);
  left: 3px;
}

.vertical div.jx-controller {
  height: 9px;
  width: 100px;
  margin-left: auto;
  margin-right: auto;
  top: -3px;
  position: relative;
}

div.jx-arrow {
  position: absolute;
  margin: auto;
  top: 0;
  bottom: 0;
  width: 0;
  height: 0;
  transition: all 0.2s ease;
}

.vertical div.jx-arrow {
  position: absolute;
  margin: 0 auto;
  left: 0;
  right: 0;
  width: 0;
  height: 0;
